import { recordedDeed } from './story-continuity.js';
import { COMPANION_DIALOGUE_V27 } from './companion-dialogue-v27.js';
import { seededRoll } from './world.js';
import { PERSONAL_STORY_TITLES } from './story-titles.js';

// Personal accounts are separate from familiarity. Only the named participant's
// own recorded decisions can create an account; queries never invent history.
export const REMEDIES=Object.freeze({
 credit:{title:'Restore the maker’s credit',days:2,cost:6,work:'file a public authorship correction and deliver a credited copy'},
 unpaid:{title:'Settle the unpaid work',days:2,cost:18,work:'pay the recorded compensation and give the worker their own settlement copy'},
 falseReport:{title:'Withdraw the false allegation',days:3,cost:10,work:'withdraw the allegation before the record keeper and notify the affected household'},
 archive:{title:'Release the restricted account',days:2,cost:8,work:'relinquish exclusive access and fund an independently held copy'},
 route:{title:'Release control of the route',days:3,cost:12,work:'withdraw your route claim and fund a private courier chosen by its household; earlier disclosures cannot be recalled'},
 gate:{title:'End the exclusive admission rule',days:2,cost:8,work:'revoke your admission restriction and record a shared access agreement'},
 suppressed:{title:'Restore the suppressed account',days:3,cost:10,work:'release the original account for its author to preserve without your permission'},
 privacy:{title:'Relinquish the private account',days:3,cost:12,work:'surrender your held copies and fund a confidential correction chosen by the affected people; circulated copies and memories remain'},
 pressure:{title:'Withdraw the coercive terms',days:3,cost:16,work:'withdraw your demand and pay for an independent settlement of the imposed terms; this purchases no forgiveness'},
});
const deedKind={take_credit:'credit',unpaid_work:'unpaid',false_report:'falseReport',exclude_archive:'archive',sell_route:'route',exclude_gate:'gate',suppress_account:'suppressed'};
const clears={restore_credit:['credit','falseReport','suppressed'],restore_credit_access:['credit','falseReport','suppressed','archive'],restore_access:['archive','suppressed'],pay_arrears:['unpaid'],release_route:['route'],open_gate:['gate']};
const companionKinds={mira:['privacy','privacy','gate','privacy','pressure'],orrin:['privacy','falseReport','archive','privacy','credit'],kest:['falseReport','route','gate','suppressed','pressure'],sable:['privacy','gate','gate','privacy','pressure'],tovin:['pressure','gate','gate','pressure','pressure'],vesper:['privacy','gate','archive','suppressed','credit']};
export function personalAccounts(s,id,{all=false}={}){
 const result=[];
 for(const arc of s.stories?.arcs||[]){
  if(arc.personId!==id)continue;const accounts=[];
  for(const [index,c]of arc.choices.entries()){
   const deed=recordedDeed(arc,c);for(const a of accounts)if(clears[deed]?.includes(a.kind))a.resolved=true;
   const kind=deedKind[deed]||(c.id==='coercion'?'pressure':null);
   if(kind)accounts.push({key:`story:${arc.id}:${index}`,source:'story',sourceId:arc.id,index,personId:id,kind,day:c.day,locationId:arc.locationId,title:arc.title||PERSONAL_STORY_TITLES[arc.id]||'The account with '+(arc.personName||'this person'),account:c.outcome,resolved:false});
  }result.push(...accounts);
 }
 const stage=s.rpg?.companionStages?.[id];
 for(const [index,c]of(stage?.choices||[]).entries())if(c.id==='scheme')result.push({key:`companion:${id}:${index}`,source:'companion',sourceId:id,index,personId:id,kind:companionKinds[id]?.[index]||'pressure',day:c.day,locationId:stage.locationId,title:COMPANION_DIALOGUE_V27[id]?.[index]?.[0]||'A shared decision',account:c.outcome,resolved:false});
 return result.filter(a=>all||!a.resolved&&!s.conversations?.repairs?.some(r=>r.key===a.key&&r.personId===id));
}
export function repairTerms(a){const t={...REMEDIES[a.kind]};if(a.kind==='unpaid'&&a.sourceId==='night_door')t.cost=22;return t;}
export function personalReadiness(s,id){
 const a=personalAccounts(s,id)[0];if(a)return `An unresolved account remains: ${a.title}. ${repairTerms(a).title}. Ordinary company is still welcome; a new pledge or active travel must wait.`;
 const pending=(s.conversations?.repairs||[]).filter(r=>r.personId===id&&r.reviewedDay===null);
 if(pending.length){const day=Math.max(...pending.map(r=>r.day+2));return s.day<day?`The remedy is recorded. Give them until day ${day}, then ask about their boundary in an ordinary conversation.`:'The remedy is recorded. Ask about their boundary in an ordinary conversation before proposing a new pledge or active travel.';}return null;
}
export function reviewPersonalRepair(s,id){if(personalAccounts(s,id).length)return;for(const r of s.conversations?.repairs||[])if(r.personId===id&&r.reviewedDay===null&&s.day>=r.day+2)r.reviewedDay=s.day;}
export function respectPersonalBoundaries(s){if(s.battle||s.phase==='retired')return;for(const p of s.companions||[])if(p.active&&personalReadiness(s,p.id)){p.active=false;const stage=s.rpg?.companionStages?.[p.id];if(stage)stage.locationId=s.locationId;}}
export function storyRepairContext(s,a){return {...a,repairAccounts:(s.conversations?.repairs||[]).filter(r=>r.key.startsWith(`story:${a.id}:`)).map(r=>({index:Number(r.key.split(':').at(-1)),kind:r.kind,day:r.day}))};}

export const COMPANION_IDENTITIES=Object.freeze({
 mira:{role:'protector and shelter keeper',concern:'A door that can be declined',ask:'What would make that door useful to someone else?',answer:'A key they can return. A place to sleep without a demand for their whole story.',share:'Tell me about a place you chose to stay. I want the small details.',boundary:'Keep a seat for me, not a claim on every evening.',updates:['I have an invitation to write, and no right to demand an address.','The reply matters. It still does not promise a return.','A room should be useful even if the person I miss never comes.','The guest made good stew. The chimney needs more attention than the guest’s name.','I want to repair the hearth without selling anybody’s route.','There are new friends at that hearth. I can keep an invitation and keep living.']},
 orrin:{role:'scholar and translator',concern:'The account left in the margin',ask:'Which reading are you trying to preserve?',answer:'The one somebody thought too ordinary to copy. Soup can be history. So can a reader’s objection.',share:'Tell me something your teachers left out. I will resist making a footnote of you.',boundary:'You may disagree with a reading. Its reader still gets a name.',updates:['I have two translations and one very hungry bell. Neither settles the other.','The learner’s laugh was a question the lesson needed.','I want copies people can read without buying a patron’s version of the past.','A marginal note can be worth more than the edition it corrects.','I can restore a footnote without hunting the person who wrote it.','The next learner has a question I cannot answer yet. That is a useful beginning.']},
 kest:{role:'scout and courier',concern:'A safe road with a private end',ask:'What makes a route safe for the person using it?',answer:'An adult guide, a checked crossing, and an end to the job. Knowing a route does not entitle us to sell its travelers.',share:'Tell me where you would go if nobody was following. You can leave the destination out.',boundary:'Ask before sharing my route. Ask again before sharing anybody else’s.',updates:['A signature is evidence of old work. It is not proof of where somebody lives now.','The dog on the child’s map is enormous. I want an adult to check the bridge.','A courier route should not need children running through danger.','The wage tally deserves its own hearing, separate from the captain’s hunt.','I will keep a copy where the household can reach it.','The watch has an end to its shift. So do I.']},
 sable:{role:'healer and clinic keeper',concern:'The end of a healing shift',ask:'Which part of the clinic needs help, and which needs quiet?',answer:'Clean linen needs hands. A patient’s account needs permission. The healer needs sleep before kindness becomes another unpaid shift.',share:'Tell me how you rest. I keep giving other people advice I forget to take.',boundary:'My closed door is part of the care, not a failure of it.',updates:['There is a bowl waiting after midnight. I would like to finish it while it is warm.','I want the queue to have a rota, so the next shift can end.','Linen can carry a donor’s name. A waiting patient should not carry their debt.','A recovery can remain private and still be worth celebrating.','The patient decides which part of the recovery becomes a story.','I have a last shift and a life after it. Neither belongs to the party.']},
 tovin:{role:'veteran and civilian watchkeeper',concern:'Work beyond the old company',ask:'What do you want the watch to protect now?',answer:'A bakery door that can shut at night. Wages people can claim without threatening a child. I have had enough standards to march behind.',share:'Tell me about work that left you tired in a good way. Mine has not always done that.',boundary:'A watch is a paid shift. It is not a private retinue.',updates:['The old token proves a wage claim. The paymaster’s child signed none of it.','The flour sack needs a guard who can leave when asked.','A room for mending straps would be more useful than another banner.','I want an inventory the claimants can inspect before anybody takes a share.','The drawing can stay by the chest. The contents still belong to the people named.','I can keep an ordinary door without becoming somebody’s standing army.']},
 vesper:{role:'bard and keeper of competing verses',concern:'A song without an owner',ask:'Which verse should the audience hear?',answer:'Let them hear that there are two. Leave the family unnamed if they ask. A good ending does not need to win somebody else’s life.',share:'Sing me the wrong version you grew up with. I promise to ask before borrowing it.',boundary:'You can pay for a performance. You cannot buy the singer’s next answer.',updates:['A mother is named in the verse. I need her permission before I need applause.','The rival can sing. I would rather answer with a verse than a locked tavern.','A teaching room needs room for the version its keeper dislikes.','The family’s account does not fit the victory refrain. That is the refrain’s problem.','I want the notebook to keep the unfinished part too.','Someone else can finish the tune. Keeping it was never the same as owning it.']},
});
export const companionRole=p=>COMPANION_IDENTITIES[p.id]?.role||({warrior:'protector',mage:'scholar',rogue:'scout',healer:'healer',bard:'bard'}[p.role]||p.role||'companion');
const CORE_IDENTITIES={
 kin:{concern:'Time beside your own life',ask:'What would you choose for an afternoon of your own?',answer:'A little room for my own work, and company that asks how it went. Raising you was part of my life. It was never all I was.',share:'Tell me the part of your day you would have told me when you were small.',boundary:'We can care for one another without choosing each other’s future.',updates:['I would like a conversation about something besides what either of us ought to do.']},
 fellow:{concern:'A practice that bears my name',ask:'Which part of the work feels like yours?',answer:'The part I can explain without repeating somebody else’s answer. I want to get good enough to sign it, then have an evening left over.',share:'Tell me what you are still learning. I am tired of pretending everybody else is finished.',boundary:'A friend can encourage my plan without becoming its owner.',updates:['I want to choose my next piece of work before somebody chooses it for me.']},
 rival:{concern:'A name beside the evidence',ask:'What question are you trying to settle?',answer:'Which observation survives being checked. I can bear being wrong. I do not want my work disappearing beneath a more fashionable signature.',share:'Tell me where your own account might be wrong. I will try to offer the same courtesy.',boundary:'We can disagree and still keep both names on the page.',updates:['I want a record that can be argued with, and a name that stays beside it.']},
 river:{concern:'The future beyond this bank',ask:'What would you keep if your plans changed?',answer:'The right to change them. A familiar home can be dear to me without making every other road a betrayal.',share:'Tell me where you would like to live for a season. We need not make a promise of it.',boundary:'Affection can be welcome while a shared household is still an unanswered question.',updates:['I would like to talk about a possible future without having to promise it tonight.']},
};
export function personalConcern(s,p){
 const identity=COMPANION_IDENTITIES[p.id]||CORE_IDENTITIES[p.id],harms=personalAccounts(s,p.id),repairs=(s.conversations?.repairs||[]).filter(r=>r.personId===p.id);if(!identity&&!harms.length&&!repairs.length)return null;
 const profile=identity||{concern:'The agreement that is still mine',ask:'What part of that agreement needs to change?',answer:'The part where my answer stopped being a choice. I want the remedy recorded before another promise.',share:'We can share ordinary news. That does not settle the earlier account.',boundary:'Company is possible. A new pledge must wait for the remedy.',updates:['I have kept the original account. I want a concrete remedy rather than another gift.']};
 const stage=Math.min(5,s.rpg?.companionStages?.[p.id]?.stage||0),last=s.rpg?.companionStages?.[p.id]?.choices.at(-1);
 const arc=(s.stories?.arcs||[]).filter(a=>a.personId===p.id&&a.choices.length).sort((a,b)=>a.choices.at(-1).day-b.choices.at(-1).day).at(-1),decision=arc?.choices.at(-1);
 const review=repairs.filter(r=>r.reviewedDay===null),ready=review.length&&review.every(r=>s.day>=r.day+2),independent=s.society?.people?.find(q=>q.sourcePersonId===p.id),own=independent?`${independent.profession}: ${independent.goal}`:null;
 const source=p.source||(s.companions||[]).find(q=>q.id===p.id),relationship=s.life?.partnerId===p.id?'partner':s.life?.courtshipId===p.id?'courtship':p.kind==='companion'?source?.active?'traveling companion':source?.recruited?'reserve companion':'acquaintance':'friend',familiarity=p.bond<35?'new':p.bond>=65?'trusted':'familiar';
 const stamp=JSON.stringify([stage,last?.day,decision?.day,harms.map(a=>a.key),repairs.length,review.length,ready,own,relationship,familiarity]);
 return {key:`concern-${s.age}-${seededRoll(s.seed,stamp,1000000000)}`,title:profile.concern,summary:profile.updates[Math.min(stage,profile.updates.length-1)],identity:profile,stage,last:(last?.day||0)>(decision?.day||0)?last?.outcome:decision?.outcome||last?.outcome,own,harms,review,ready,relationship,familiarity};
}
